{
  "entities": [
    {
      "type": "CHOROBA",
      "name": "choroby",
      "description": "Stany wymienione w punkcie a) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "choroby, niepełnosprawności fizycznej, zaburzeń psychicznych lub zaburzeń zachowania sklasyfikowanych jako F00-F99 w rozumieniu Międzynarodowej Klasyfikacji Chorób i Problemów Zdrowotnych ICD-10 oraz medycznych lub chirurgicznych skutków ich leczenia, lumbago, rwy kulszowej, zwyrodnienia kręgosłupa, dyskopatii, kręgozmyku, przepukliny krążka miażdżystego, przepukliny, zatrucia ptomainami lub infekcji bakteryjnej (z wyjątkiem infekcji ropnej powstałej w wyniku przypadkowego skaleczenia lub zranienia)"
    },
    {
      "type": "LEK",
      "name": "leków",
      "description": "Substancje wymienione w punkcie b) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "wypadku wynikłego z faktu pozostawania odpowiednio przez Ubezpieczonego, Małżonka lub Partnera, lub Dziecko w stanie po spożyciu alkoholu, leków, z wyjątkiem zażywanych zgodnie z zaleceniem lekarza, narkotyków lub innych substancji toksycznych"
    },
    {
      "type": "SAMOOKALECZENIE",
      "name": "samookaleczenia",
      "description": "Czynność wymieniona w punkcie c) wyłączająca odpowiedzialność ubezpieczyciela",
      "dowód": "samookaleczenia lub okaleczenia na prośbę odpowiednio Ubezpieczonego, Małżonka lub Partnera, lub Dziecka, niezależnie od stanu ich poczytalności"
    },
    {
      "type": "SKAŻENIE",
      "name": "masowym skażeniem chemicznym, biologicznym lub radioaktywnym",
      "description": "Zdarzenie wymienione w punkcie d) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "zdarzenia związanego z masowym skażeniem chemicznym, biologicznym lub radioaktywnym spowodowanym działaniem broni lub urządzenia wykorzystującego energię rozszczepienia jądrowego lub promieniotwórczość"
    },
    {
      "type": "DZIAŁANIA WOJENNE",
      "name": "działań wojennych",
      "description": "Zdarzenie wymienione w punkcie e) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "działań wojennych, czynnego udziału w aktach terroru lub masowych rozruchach społecznych"
    },
    {
      "type": "PRZESTĘPSTWO",
      "name": "umyślnego przestępstwa",
      "description": "Czynność wymieniona w punkcie f) wyłączająca odpowiedzialność ubezpieczyciela",
      "dowód": "obrażeń odniesionych na skutek usiłowania popełnienia lub popełnienia umyślnego przestępstwa, umyślnego udziału w innym czynie zabronionym lub stawiania oporu podczas aresztowania lub zatrzymania"
    },
    {
      "type": "CZYNNOŚCI SŁUŻBOWE",
      "name": "wykonywania czynności służbowych/zawodowych właściwych dla policji, wojska, Straży Granicznej, straży pożarnej, straży gminnej (miejskiej), bądź jednostki pomocniczej lub cywilnej działającej w strukturach armii, niezależnie od formy zatrudnienia lub pełnienia służby",
      "description": "Czynności wymienione w punkcie g) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "wykonywania czynności służbowych/zawodowych właściwych dla policji, wojska, Straży Granicznej, straży pożarnej, straży gminnej (miejskiej), bądź jednostki pomocniczej lub cywilnej działającej w strukturach armii, niezależnie od formy zatrudnienia lub pełnienia służby"
    },
    {
      "type": "SPORT WYCZYNOWY",
      "name": "zawodowego i wyczynowego uprawiania sportu",
      "description": "Aktywność wymieniona w punkcie h) wyłączająca odpowiedzialność ubezpieczyciela",
      "dowód": "zawodowego i wyczynowego uprawiania sportu"
    },
    {
      "type": "SPORT EKSTREMALNY",
      "name": "wspinaczki, skoków spadochronowych, lotów szybowcowych, paralotniarstwa, nurkowania, speleologii, sportów walki, sportów motorowych lub motorowodnych, uczestnictwa w rajdach samochodowych lub rajdach motocyklowych, jazdy motocyklem poza drogami w rozumieniu przepisów o ruchu drogowym",
      "description": "Aktywności wymienione w punkcie i) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "uprawiania wspinaczki, skoków spadochronowych, lotów szybowcowych, paralotniarstwa, nurkowania, speleologii, sportów walki, sportów motorowych lub motorowodnych, uczestnictwa w rajdach samochodowych lub rajdach motocyklowych, jazdy motocyklem poza drogami w rozumieniu przepisów o ruchu drogowym"
    },
    {
      "type": "ZAWODY",
      "name": "zawodach z użyciem pojazdów kołowych, zawodach z użyciem łodzi lub nart wodnych lub zawodach konnych",
      "description": "Aktywności wymienione w punkcie j) wyłączające odpowiedzialność ubezpieczyciela",
      "dowód": "uczestnictwa w zawodach z użyciem pojazdów kołowych, zawodach z użyciem łodzi lub nart wodnych lub zawodach konnych"
    },
    {
      "type": "PODRÓŻ",
      "name": "podróży jakimkolwiek statkiem powietrznym w charakterze pasażera lub innym, z wyjątkiem lotu w charakterze pasażera samolotem pasażerskich licencjonowanych linii lotniczych",
      "description": "Aktywność wymieniona w punkcie k) wyłączająca odpowiedzialność ubezpieczyciela",
      "dowód": "podróży jakimkolwiek statkiem powietrznym w charakterze pasażera lub innym, z wyjątkiem lotu w charakterze pasażera samolotem pasażerskich licencjonowanych linii lotniczych"
    }
  ]
}
